fn netdev_get_tx_queue(dev: *const net_device, index: u32) -> *mut netdev_queue {
DEBUG_NET_WARN_ON_ONCE!();
unsafe { (*dev)._tx }.wrapping_offset(index as isize)
}

fn netdev_priv(dev: *const net_device) -> *mut () {
(unsafe { core::ptr::addr_of!((*dev).r#priv) as *const u8 }) as *mut ()
}

fn netdev_lock(dev: *mut net_device) {
unsafe { mutex_lock(core::ptr::addr_of_mut!((*dev).lock)) };
}

fn netdev_unlock(dev: *mut net_device) {
unsafe { mutex_unlock(core::ptr::addr_of_mut!((*dev).lock)) };
}

// Default NAPI poll() weight
// Device drivers are strongly advised to not use bigger value
fn netif_napi_add_weight(dev: *mut net_device, napi: *mut napi_struct, poll: Option<unsafe extern "C" fn(*mut napi_struct, i32) -> i32>, weight: i32) {
netdev_lock(dev);
unsafe { netif_napi_add_weight_locked(dev, napi, poll, weight) };
netdev_unlock(dev);
}

fn netif_napi_add(dev: *mut net_device, napi: *mut napi_struct, poll: Option<unsafe extern "C" fn(*mut napi_struct, i32) -> i32>) {
netif_napi_add_weight(dev, napi, poll, 64i32);
}

