fn netif_wake_queue(dev: *mut net_device) {
unsafe { netif_tx_wake_queue(netdev_get_tx_queue(dev as *const net_device, 0u32)) };
}

#[inline(always)]
fn netif_tx_stop_queue(dev_queue: *mut netdev_queue) {
// Paired with READ_ONCE() from dev_watchdog()
loop {
loop {
if !(__native_word!() || ((const { core::mem::size_of::<u64>() }) as u64) == ((const { core::mem::size_of::<i64>() }) as u64)) {
unsafe { __compiletime_assert_721() };
unsafe { core::hint::unreachable_unchecked() };
}
if true {
break;
}
}
__WRITE_ONCE!((*dev_queue).trans_start, unsafe { core::ptr::read_volatile(core::ptr::addr_of!(jiffies)) });
if true {
break;
}
}
// This barrier is paired with smp_mb() from dev_watchdog()
smp_mb__before_atomic!();
// Must be an atomic op see netif_txq_try_stop()
set_bit(0i64, (unsafe { core::ptr::addr_of_mut!((*dev_queue).state) }) as *mut u64);
}

fn netif_stop_queue(dev: *mut net_device) {
netif_tx_stop_queue(netdev_get_tx_queue(dev as *const net_device, 0u32));
}

fn netdev_tx_sent_queue(dev_queue: *mut netdev_queue, bytes: u32) {
dql_queued(unsafe { core::ptr::addr_of_mut!((*dev_queue).dql) }, bytes);
if likely!(dql_avail((unsafe { core::ptr::addr_of_mut!((*dev_queue).dql) }) as *const dql) >= 0) != 0 {
return;
}
// Paired with READ_ONCE() from dev_watchdog()
loop {
loop {
if !(__native_word!() || ((const { core::mem::size_of::<u64>() }) as u64) == ((const { core::mem::size_of::<i64>() }) as u64)) {
unsafe { __compiletime_assert_722() };
unsafe { core::hint::unreachable_unchecked() };
}
if true {
break;
}
}
__WRITE_ONCE!((*dev_queue).trans_start, unsafe { core::ptr::read_volatile(core::ptr::addr_of!(jiffies)) });
if true {
break;
}
}
// This barrier is paired with smp_mb() from dev_watchdog()
smp_mb__before_atomic!();
set_bit(1i64, (unsafe { core::ptr::addr_of_mut!((*dev_queue).state) }) as *mut u64);
// The XOFF flag must be set before checking the dql_avail below,
// because in netdev_tx_completed_queue we update the dql_completed
// before checking the XOFF flag.
smp_mb__after_atomic!();
// check again in case another CPU has just made room avail
if unlikely!(dql_avail((unsafe { core::ptr::addr_of_mut!((*dev_queue).dql) }) as *const dql) >= 0) != 0 {
clear_bit(1i64, (unsafe { core::ptr::addr_of_mut!((*dev_queue).state) }) as *mut u64);
}
}

fn netdev_sent_queue(dev: *mut net_device, bytes: u32) {
netdev_tx_sent_queue(netdev_get_tx_queue(dev as *const net_device, 0u32), bytes);
}

fn netdev_tx_completed_queue(dev_queue: *mut netdev_queue, pkts: u32, bytes: u32) {
if unlikely!(bytes == 0) != 0 {
return;
}
unsafe { dql_completed(core::ptr::addr_of_mut!((*dev_queue).dql), bytes) };
// Without the memory barrier there is a small possibility that
// netdev_tx_sent_queue will miss the update and cause the queue to
// be stopped forever
loop {
kcsan_mb!();
unsafe {
core::arch::asm!("lock addl $0,-4(%rsp)", options(nostack, att_syntax));
}
if true {
break;
}
}
// NOTE: netdev_txq_completed_mb() assumes this exists
if unlikely!(dql_avail((unsafe { core::ptr::addr_of_mut!((*dev_queue).dql) }) as *const dql) < 0) != 0 {
return;
}
if test_and_clear_bit(1i64, (unsafe { core::ptr::addr_of_mut!((*dev_queue).state) }) as *mut u64) {
unsafe { netif_schedule_queue(dev_queue) };
}
}

fn netdev_completed_queue(dev: *mut net_device, pkts: u32, bytes: u32) {
netdev_tx_completed_queue(netdev_get_tx_queue(dev as *const net_device, 0u32), pkts, bytes);
}

fn netdev_tx_reset_queue(q: *mut netdev_queue) {
clear_bit(1i64, (unsafe { core::ptr::addr_of_mut!((*q).state) }) as *mut u64);
unsafe { dql_reset(core::ptr::addr_of_mut!((*q).dql)) };
}

fn netdev_tx_reset_subqueue(dev: *const net_device, qid: u32) {
netdev_tx_reset_queue(netdev_get_tx_queue(dev, qid));
}

fn netdev_reset_queue(dev_queue: *mut net_device) {
netdev_tx_reset_subqueue(dev_queue as *const net_device, 0u32);
}

fn netif_running(dev: *const net_device) -> bool {
test_bit__2!(0i32, unsafe { core::ptr::addr_of!((*dev).state) }) != 0
}

fn dev_kfree_skb_any(skb: *mut sk_buff) {
unsafe { dev_kfree_skb_any_reason(skb, 2u32) };
}

fn napi_gro_receive(napi: *mut napi_struct, skb: *mut sk_buff) -> u32 {
unsafe { gro_receive_skb(core::ptr::addr_of_mut!((*napi).gro), skb) }
}

fn netif_carrier_ok(dev: *const net_device) -> bool {
test_bit__2!(2i32, unsafe { core::ptr::addr_of!((*dev).state) }) == 0
}

fn netif_msg_init(debug_value: i32, default_msg_enable_bits: i32) -> u32 {
// use default
if debug_value < 0 || (debug_value as u64) >= (core::mem::size_of::<u32>() as u64).wrapping_mul(8) {
return default_msg_enable_bits as u32;
}
if debug_value == 0 {
return 0;
}
// no output
// set low N bits
(1u32 << debug_value).wrapping_sub(1)
}

