// dev_addrs walker. Should be used only for read access. Call with
// rcu_read_lock held.
fn __dev_addr_set(dev: *mut net_device, addr: *const (), len: u64) {
unsafe { dev_addr_mod(dev, 0u32, addr, len) };
}

// The list of packet types we will receive (as opposed to discard)
// and the routines to invoke.
//
// Why 16. Because with 16 the only overlap we get on a hash of the
// low nibble of the protocol value is RARP/SNAP/X.25.
//
// 	0800	IP
// 	0001	802.3
// 	0002	AX.25
// 	0004	802.2
// 	8035	RARP
// 	0005	SNAP
// 	0805	X.25
// 	0806	ARP
// 	8137	IPX
// 	0009	Localtalk
// 	86DD	IPv6
// Note: Avoid these macros in fast path, prefer per-cpu or per-queue counters.
fn is_zero_ether_addr(addr: *const u8) -> bool {
(unsafe { *(addr as *const u32) }) | (((unsafe { *(addr.wrapping_offset(4 as isize) as *const u16) }) as i32) as u32) == 0
}

fn is_multicast_ether_addr(addr: *const u8) -> bool {
let a: u32 = unsafe { *(addr as *const u32) };
1 & a != 0
}

fn is_valid_ether_addr(addr: *const u8) -> bool {
// FF:FF:FF:FF:FF:FF is a multicast address so we don't need to
// explicitly check for it here.
!is_multicast_ether_addr(addr) && !is_zero_ether_addr(addr)
}

fn eth_random_addr(addr: *mut u8) {
unsafe { get_random_bytes(addr as *mut (), 6u64) };
let __v0: *mut u8 = addr.wrapping_offset(0 as isize);
unsafe {
*__v0 = ((*__v0 as i32) & 254) as u8;
}
// clear multicast bit
let __v3: *mut u8 = addr.wrapping_offset(0 as isize);
unsafe {
*__v3 = ((*__v3 as i32) | 2) as u8;
}
// set local assignment bit (IEEE802)
}

fn eth_hw_addr_random(dev: *mut net_device) {
let mut addr: [u8; 6] = [0u8; 6];
eth_random_addr(addr.as_mut_ptr() as *mut u8);
__dev_addr_set(dev, addr.as_mut_ptr() as *const (), 6u64);
unsafe {
(*dev).addr_assign_type = 1;
}
}

fn eth_hw_addr_set(dev: *mut net_device, addr: *const u8) {
__dev_addr_set(dev, addr as *const (), 6u64);
}

