#[repr(C)]
#[derive(Clone, Copy)]
struct tcphdr {
    source: u16,
    dest: u16,
    seq: u32,
    ack_seq: u32,
    __slate_bits_0: __slate_bits::__SlateBits1531U0,
    window: u16,
    check: u16,
    urg_ptr: u16,
}


// for TCP_MD5SIG socket option
fn tcp_hdr(skb: *const sk_buff) -> *mut tcphdr {
skb_transport_header(skb) as *mut tcphdr
}

fn __tcp_hdrlen(th: *const tcphdr) -> u32 {
((unsafe { (*th).__slate_bits_0.__get_doff() }) as i32).wrapping_mul(4) as u32
}

fn tcp_hdrlen(skb: *const sk_buff) -> u32 {
__tcp_hdrlen(tcp_hdr(skb) as *const tcphdr)
}

fn skb_tcp_all_headers(skb: *const sk_buff) -> i32 {
(skb_transport_offset(skb) as u32).wrapping_add(tcp_hdrlen(skb)) as i32
}

