// Flag: "Don't Fragment"
// Flag: "More Fragments"
// "Fragment Offset" part
// Total octets in header.
fn __vlan_hwaccel_clear_tag(skb: *mut sk_buff) {
unsafe {
(*skb).__slate_anon_20.__slate_anon_0.__slate_anon_34.vlan_all = 0;
}
}

fn __vlan_hwaccel_copy_tag(dst: *mut sk_buff, src: *const sk_buff) {
unsafe {
(*dst).__slate_anon_20.__slate_anon_0.__slate_anon_34.vlan_all = (*src).__slate_anon_20.__slate_anon_0.__slate_anon_34.vlan_all;
}
}

fn __vlan_hwaccel_put_tag(skb: *mut sk_buff, vlan_proto: u16, vlan_tci: u16) {
unsafe {
(*skb).__slate_anon_20.__slate_anon_0.__slate_anon_34.__slate_anon_1.vlan_proto = vlan_proto;
}
unsafe {
(*skb).__slate_anon_20.__slate_anon_0.__slate_anon_34.__slate_anon_1.vlan_tci = vlan_tci;
}
}

