fn sky2_is_copper(hw: *const sky2_hw) -> i32 {
((unsafe { (*hw).flags }) & 2 == 0) as i32
}

fn sky2_read32(hw: *const sky2_hw, reg: u32) -> u32 {
readl(((unsafe { ((*hw).regs as *const u8).wrapping_offset(reg as isize) }) as *mut ()) as *const ())
}

