fn sky2_power_on(hw: *mut sky2_hw) {
// switch power to VCC (WA for VAUX problem)
sky2_write8(hw as *const sky2_hw, 7u32, 166u8);
// disable Core Clock Division,
sky2_write32(hw as *const sky2_hw, 288u32, 1u32);
if ((unsafe { (*hw).chip_id }) as i32) == 179 && ((unsafe { (*hw).chip_rev }) as i32) > 1 {
sky2_write8(hw as *const sky2_hw, 285u32, 119u8);
} else {
sky2_write8(hw as *const sky2_hw, 285u32, 0u8);
}
// enable bits are inverted
if (unsafe { (*hw).flags }) & 128 != 0 {
let mut reg: u32 = 0;
sky2_pci_write32(hw, 128u32, 0u32);
reg = sky2_pci_read32(hw as *const sky2_hw, 132u32);
// set all bits to 0 except bits 15..12 and 8
reg &= 61440;
sky2_pci_write32(hw, 132u32, reg);
reg = sky2_pci_read32(hw as *const sky2_hw, 136u32);
// set all bits to 0 except bits 28 & 27
reg &= 402653184;
sky2_pci_write32(hw, 136u32, reg);
sky2_pci_write32(hw, 148u32, 0u32);
sky2_write16(hw as *const sky2_hw, 4u32, 32768u16);
// Enable workaround for dev 4.107 on Yukon-Ultra & Extreme
reg = sky2_read32(hw as *const sky2_hw, 348u32);
reg |= 8192;
sky2_write32(hw as *const sky2_hw, 348u32, reg);
sky2_read32(hw as *const sky2_hw, 348u32);
}
// Turn on "driver loaded" LED
sky2_write16(hw as *const sky2_hw, 4u32, 512u16);
}

fn sky2_power_aux(hw: *mut sky2_hw) {
if ((unsafe { (*hw).chip_id }) as i32) == 179 && ((unsafe { (*hw).chip_rev }) as i32) > 1 {
sky2_write8(hw as *const sky2_hw, 285u32, 0u8);
} else {
sky2_write8(hw as *const sky2_hw, 285u32, 119u8);
}
// enable bits are inverted
// switch power to VAUX if supported and PME from D3cold
let __v0: bool = sky2_read32(hw as *const sky2_hw, 4u32) & 65536 != 0 && unsafe { pci_pme_capable((*hw).pdev, 4i32) };
if __v0 {
sky2_write8(hw as *const sky2_hw, 7u32, 169u8);
}
// turn off "driver loaded LED"
sky2_write16(hw as *const sky2_hw, 4u32, 256u16);
}

fn sky2_gmac_reset(hw: *mut sky2_hw, port: u32) {
let mut reg: u16 = 0;
// disable all GMAC IRQ's
sky2_write8(hw as *const sky2_hw, SK_REG!(port, 3852i32), 0u8);
gma_write16(hw as *const sky2_hw, port, 52i32, 0u16); // clear MC hash
gma_write16(hw as *const sky2_hw, port, 56i32, 0u16);
gma_write16(hw as *const sky2_hw, port, 60i32, 0u16);
gma_write16(hw as *const sky2_hw, port, 64i32, 0u16);
reg = gma_read16(hw as *const sky2_hw, port, 12u32);
reg = ((reg as i32) | (32768 | 16384)) as u16;
gma_write16(hw as *const sky2_hw, port, 12i32, reg);
}

/// flow control to advertise bits
