// disable energy detect
let __v13: u16 = ((ctrl as i32) & !768) as u16;
ctrl = __v13;
// enable automatic crossover
let __v14: u16 = ctrl;
ctrl = ((__v14 as i32) | PHY_M_PC_MDI_XMODE!(3i32)) as u16;
